/* ===== APP PART 12: Baseline builder (BOQ -> mapping sheet, resources, logic, durations, CPM preview, XER) ===== */
const bbFresh = () => ({ file: '', sheets: null, sheet: '', rows: null, col: null, items: [], total: 0, skipped: 0, declared: null, bills: {}, over: {}, def: { E: 5, P: 30, C: 55, T: 10 }, set: { name: 'New project baseline', wbsMode: 'phase', prefix: 'PRJ', start: '2026-11-01', currency: 'SAR', price: 1, days: [7, 1, 2, 3, 4, 5], hrs: 8, holText: '', agg: 0, crews: 1, prodCase: 'typical', clim: 0.9, outdoor: ['Earthworks', 'Roads & paving', 'Utilities & drainage', 'Concrete & structure'], dur: { E: 20, S: 14, P: 60, C: 30, T: 10, H: 5 } }, lk: { edit: {}, removed: [], manual: [], accepted: false }, prod: [], prodFile: '', durOv: {}, crewOv: {}, stat: {}, ack: false, ai: { on: { boq: true, class: true, split: true, logic: true, final: false }, res: {}, busy: '' }, R: null, page: 0, billF: '', q: '', note: '', mid: 1 });
S.bb = bbFresh();
function bbRebuild() {
  const B = S.bb; if (!B.rows || !B.col || B.col.header < 0 || B.col.amount < 0 || B.col.item < 0) { B.items = []; B.R = null; return; }
  const r = E.bbRead(B.rows, B.col); B.items = r.items; B.total = r.total; B.skipped = r.skipped; B.skippedRows = r.skippedRows || []; B.declared = r.declared;
  const old = B.bills, nb = {}, stat = {}, votes = {};
  for (const it of B.items) {
    const s = stat[it.bill] = stat[it.bill] || { n: 0, amt: 0 }; s.n++; s.amt += it.amount; const vt = votes[it.bill] = votes[it.bill] || {};
    const g = E.bbGuess(it.bill + ' ' + it.sect + ' ' + it.desc); it.disc = g.disc; it.sug = g.preset; it.conf = g.preset === 'def' ? 'low' : 'ok'; vt[g.preset] = (vt[g.preset] || 0) + 1;
  }
  for (const k in stat) {
    const o = old[k]; if (o && !o.auto) { nb[k] = { preset: o.preset, split: o.split, auto: false, s: o.s, h: o.h }; continue; }
    const gb = E.bbGuess(k); const best = gb.preset !== 'def' ? gb.preset : Object.entries(votes[k]).sort((x, y) => y[1] - x[1])[0][0];
    nb[k] = { preset: best, split: null, auto: true, s: o ? o.s : undefined, h: o ? o.h : undefined };
  }
  B.stat = stat; B.bills = nb; bbRefresh();
}
function bbRefresh() { const B = S.bb; B.R = B.items.length ? E.bbBuild(B) : null; }
async function loadBb(file) {
  const B = S.bb;
  try {
    B.file = file.name; B.over = {}; B.bills = {}; B.page = 0; B.note = ''; B.lk = { edit: {}, removed: [], manual: [], accepted: false }; B.durOv = {}; B.crewOv = {};
    if (/\.pdf$/i.test(file.name)) {
      toast('Reading the PDF…'); const pages = await pdfPages(file, null, { ocr: false }); const rows = E.bbReadPdfLines(pages.map(p => p.text).join('\n'));
      B.sheets = { PDF: rows }; B.sheet = 'PDF'; B.rows = rows; B.col = { header: 0, item: 0, desc: 1, unit: 2, qty: 3, rate: 4, amount: 5, part: -1, area: -1 };
      B.note = rows.length > 1 ? 'PDF read from the text layer: ' + (rows.length - 1) + ' lines looked like BOQ rows. A PDF is never exact, so check the totals against the BOQ summary page.' : 'No BOQ rows could be read from this PDF (scanned, or an unusual layout). Use the Excel BOQ if you have it.';
    } else {
      const sh = await readSheetRows(file); B.sheets = sh; B.sheet = Object.keys(sh)[0]; B.rows = sh[B.sheet]; B.col = E.guessBoqColumns(B.rows); B.col.area = -1;
    }
    if (!B.set.name || B.set.name === 'New project baseline') B.set.name = file.name.replace(/\.[^.]+$/, '');
    bbRebuild();
  } catch (e) { console.error(e); toast(e.message, 'bad'); }
  viewBuilder();
}
async function loadProd(file) {
  const B = S.bb; try { const sh = await readSheetRows(file); let all = []; for (const n of Object.keys(sh)) all = all.concat(E.bbProdRead(sh[n])); if (!all.length) { toast('No productivity rows found. Needed columns: unit, output per day per crew (and optionally trade/keyword, crews, note).', 'warn'); return; } B.prod = all; B.prodFile = file.name; bbRefresh(); viewBuilder(); toast(all.length + ' productivity rates loaded', 'ok'); } catch (e) { console.error(e); toast(e.message, 'bad'); }
}
/* ---- save / open the builder ---- */
async function bbSave() {
  const B = S.bb; if (!B.rows) { toast('Nothing to save yet – load a BOQ first.', 'bad'); return; }
  const o = { tool: 'baseline-builder', version: 2, saved: new Date().toISOString(), file: B.file, sheets: B.sheets, sheet: B.sheet, col: B.col, bills: B.bills, over: B.over, def: B.def, set: B.set, lk: B.lk, prod: B.prod, prodFile: B.prodFile, durOv: B.durOv, crewOv: B.crewOv, aiOn: B.ai.on, mid: B.mid, warnWhy: B.warnWhy || {}, logicOk: !!B.logicOk, aiProd: B.aiProd || {} };
  const blob = await gzipStr(JSON.stringify(o)); download(blob, (B.set.prefix || 'BOQ') + '_baseline_builder.brtb'); toast('Builder saved (' + (blob.size / 1048576).toFixed(1) + ' MB) – includes the BOQ.', 'ok');
}
async function bbOpen(file) {
  try {
    const o = await readBundle(file); if (!o || o.tool !== 'baseline-builder') throw new Error('This is not a Baseline builder file.');
    const B = Object.assign(bbFresh(), { file: o.file, sheets: o.sheets, sheet: o.sheet, col: o.col, bills: o.bills || {}, over: o.over || {}, def: o.def, lk: Object.assign({ edit: {}, removed: [], manual: [], accepted: false }, o.lk), prod: o.prod || [], prodFile: o.prodFile || '', durOv: o.durOv || {}, crewOv: o.crewOv || {}, mid: o.mid || 1, warnWhy: o.warnWhy || {}, logicOk: !!o.logicOk, aiProd: o.aiProd || {} });
    B.set = Object.assign(bbFresh().set, o.set); B.set.hrs = 8; B.set.dur = Object.assign({ E: 20, S: 14, P: 60, C: 30, T: 10, H: 5 }, (o.set || {}).dur); if (o.aiOn) B.ai.on = o.aiOn;
    B.rows = B.sheets[B.sheet]; S.bb = B; bbRebuild(); viewBuilder(); toast('Builder restored', 'ok');
  } catch (e) { console.error(e); toast(e.message, 'bad'); }
}
const SEL = (id, opts, cur) => `<select ${id}>${opts.map(([v, t]) => `<option value="${v}" ${String(v) === String(cur) ? 'selected' : ''}>${esc(t)}</option>`).join('')}</select>`;
const bbLab = p => (p.area ? p.area + ' / ' : '') + p.bill;
const bbDt = d => d == null ? '' : E.fmtDate(d);
