  <div class="grid g4" style="align-items:end">${E.BB_STAGES.map(s => `<label class="f"><span>${esc(s.name)} %</span><input type="number" step="any" data-bdef="${s.k}" value="${d[s.k]}"></label>`).join('')}<div>${dsum === 100 ? qchip('Total 100%', 'ok') : qchip('Total ' + dsum + '% – must be 100%', 'bad')}</div></div>
