/* ---------- Claude checkpoints (optional) ---------- */
const BB_AI = [
  { id: 'boq', task: 'bb_boq', t: 'BOQ sanity', d: 'Looks for odd units, rates that do not fit the description, likely duplicates and rows that look like totals.' },
  { id: 'class', task: 'bb_class', t: 'Classification', d: 'Checks the preset suggested for each bill and the doubtful items, and proposes a better one where needed.' },
  { id: 'split', task: 'bb_split', t: 'Stage split', d: 'Asks whether the percentages suit each bill (for example no testing stage for earthworks).' },
  { id: 'logic', task: 'bb_logic', t: 'Logic', d: 'Reviews the sequencing between bills, the stage order and the durations, and proposes missing or wrong links. Suggestions only; nothing is added to the schedule.' },
  { id: 'final', task: 'bb_final', t: 'Final review', d: 'A last read of the whole result: totals, split by stage, warnings and what a planner should still check.' }
];
function bbAiData(id) {
  const B = S.bb, R = B.R, items = B.items.slice(0, 400).map(i => ({ item: i.item, desc: i.desc.slice(0, 90), unit: i.unit, qty: i.qty, rate: i.rate, amount: Math.round(i.amount), bill: i.bill, suggested: i.sug, conf: i.conf }));
  const bills = Object.entries(B.bills).map(([n, b]) => ({ bill: n, items: (B.stat[n] || {}).n, value: Math.round((B.stat[n] || {}).amt || 0), preset: b.split ? 'custom' : b.preset, split: b.split || (E.BB_PRESETS[b.preset] && E.BB_PRESETS[b.preset].split) || B.def }));
  const presets = Object.entries(E.BB_PRESETS).map(([k, v]) => ({ key: k, name: v.name, split: v.split || 'project default' }));
  if (id === 'boq') return { items };
  if (id === 'class') return { presets, bills, items: items.filter(i => i.conf === 'low') };
  if (id === 'split') return { presets, bills, default: B.def, stages: E.BB_STAGES.map(s => s.name) };
  if (id === 'logic') return { structure: 'Each BOQ item has its own chain Engineering → Submittal/approval (optional) → Procurement → Construction → Testing → Handover (optional), finish-to-start. Each bill has a construction-start and a complete milestone; all bills start after the project start and finish into the project completion.', sequencing_between_bills: R.tmpl.map(t => ({ from: t.pred.bill, to: t.succ.bill, type: t.type, lag_days: t.lag, status: t.status })), durations: { placeholders: B.set.dur, productivity_rates_loaded: B.prod.length }, preview: R.cpm ? { finish_working_days: R.cpm.finish, longest_path: R.cpm.path.filter(a => !a.mile).slice(0, 25).map(a => a.code + ' ' + a.dur + 'd') } : 'logic has a loop', bills: bills.map(b => ({ bill: b.bill, value: b.value })), items: items.slice(0, 120).map(i => ({ item: i.item, desc: i.desc, bill: i.bill })) };
  return { total_boq: Math.round(R.totAmt), budget_in_p6: Math.round(R.totCost), by_stage: E.BB_STAGES.concat(E.BB_EXTRA).map(s => ({ stage: s.name, activities: R.byStage[s.k].n, value: Math.round(R.byStage[s.k].amt) })), bills, issues: R.issues.slice(0, 30).map(i => i.txt), finish_working_days: R.cpm ? R.cpm.finish : null };
}
const BB_SYS = 'You are a senior construction planning engineer reviewing a BOQ-to-schedule conversion for a Primavera P6 baseline. Be concrete and brief. Never state project facts you cannot see in the data; if unsure say so. Reply ONLY with a JSON array of findings: [{"ref":"bill name or item no. or short label","severity":"info|warn|bad","issue":"what is wrong or doubtful","suggestion":"what to do","preset":"optional preset key from the list, only when you propose changing a bill or item to that preset","link":"optional, for logic: predecessor -> successor (type, lag)"}]. Return [] if you find nothing. At most 15 findings.';
function bbAiHtml() {
  const B = S.bb, A = B.ai, on = BB_AI.filter(c => A.on[c.id]);
  const est = on.reduce((s, c) => s + estimateCost(c.task, JSON.stringify(bbAiData(c.id)).length, 1500), 0);
  let h = `<section class="card"><h2>9. Claude double-check <small>optional</small></h2><p class="hint" style="margin-top:0">Choose where Claude may look. Each checkpoint sends only the BOQ lines, bills and results it needs to the Claude API with your key (Setup → AI). Claude only suggests; nothing changes until you apply it.</p>
  ${S.cfg.ai.on && S.cfg.ai.key ? '' : `<div class="warnbox">AI is off or has no key. Switch it on in Setup → AI to use these checks.</div>`}
  <div class="dlist">${BB_AI.map(c => `<label style="display:block;margin:6px 0"><input type="checkbox" data-bai="${c.id}" ${A.on[c.id] ? 'checked' : ''}> <b>${esc(c.t)}</b> <small class="hint">${esc(c.d)} · ${esc(modelFor(c.task))}</small></label>`).join('')}</div>
  <div class="actions"><button class="btn" data-bairun="1" ${A.busy || !on.length ? 'disabled' : ''}>${A.busy ? 'Checking ' + esc(A.busy) + '…' : 'Run selected checks'}</button><span class="hint">≈ $${est.toFixed(3)} estimated, ${on.length} checkpoint(s) · BOQ text and rates leave this computer</span></div>`;
  for (const c of BB_AI) { const r = A.res[c.id]; if (!r) continue; h += `<h3 class="h3" style="margin-top:14px">${esc(c.t)}</h3>` + (r.err ? `<div class="warnbox">${esc(r.err)}</div>` : !r.f.length ? `<p>${qchip('Nothing found', 'ok')}</p>` : `<div class="scroll" style="max-height:340px"><table class="tbl compact"><thead><tr><th>Ref</th><th></th><th>Finding</th><th>Suggestion</th><th></th></tr></thead><tbody>${r.f.map((f, i) => `<tr><td>${esc(f.ref)}</td><td>${qchip(f.severity || 'info', f.severity === 'bad' ? 'bad' : f.severity === 'warn' ? 'warn' : '')}</td><td>${esc(f.issue)}</td><td>${esc(f.suggestion || '')}${f.link ? '<br><small>Link: ' + esc(f.link) + '</small>' : ''}</td><td>${f.preset && E.BB_PRESETS[f.preset] && E.BB_PRESETS[f.preset].split ? `<button class="btn" data-baiapp="${c.id}:${i}">Apply ${esc(E.BB_PRESETS[f.preset].name.split(' (')[0])}</button>` : ''}</td></tr>`).join('')}</tbody></table></div>`); }
  return h + `</section>`;
}
async function bbAiRun() {
  const B = S.bb, A = B.ai; if (!aiReady()) return;
  for (const c of BB_AI.filter(c => A.on[c.id])) {
    A.busy = c.t; viewBuilder();
    try { const txt = await callClaude(c.task, BB_SYS + ' Task: ' + c.t + ' – ' + c.d, JSON.stringify(bbAiData(c.id)), 2500); const f = parseJson(txt); A.res[c.id] = { f: Array.isArray(f) ? f : [] }; if (!Array.isArray(f)) A.res[c.id].err = 'Claude did not return a list I could read.'; }
    catch (e) { A.res[c.id] = { f: [], err: e.message }; }
  }
  A.busy = ''; viewBuilder();
}
function bbAiApply(key) {
  const B = S.bb, [id, i] = key.split(':'), f = B.ai.res[id].f[+i], p = E.BB_PRESETS[f.preset]; if (!p || !p.split) return;
  if (B.bills[f.ref]) { B.bills[f.ref].preset = f.preset; B.bills[f.ref].split = null; B.bills[f.ref].auto = false; }
  else { const it = B.items.find(x => x.item === f.ref); if (!it) { toast('Could not find ' + f.ref, 'warn'); return; } B.over[it.n] = Object.assign({}, p.split); }
  B.ack = false; B.logicOk = false; bbRefresh(); viewBuilder(); toast('Applied ' + p.name, 'ok');
}

/* ---------- productivity gaps: Claude suggests ranges, the engineer decides ---------- */
const BB_PROD_SYS = 'You are a senior construction planning engineer. For each work group give typical daily output per crew in the unit given, as a LOW, TYPICAL and HIGH value. You have no verified source for the region or project, so say where you are unsure. Reply ONLY with a JSON array: [{"id":"<id as given>","low":n,"typical":n,"high":n,"crew":"typical crew make-up","conditions":"assumed conditions (access, weather, method)","basis":"general industry experience; no verified source","confidence":"low|medium|high","unsure":"what could make this wrong"}]. Never invent a source or standard number.';
function bbGapData(B) { return E.bbGaps(B).slice(0, 40).map(g => ({ id: g.key, work: String(g.desc || '').slice(0, 120), unit: g.unit, items: g.n, total_quantity: Math.round(g.qty) })); }
function bbGapHtml(B) {
  const gaps = E.bbGaps(B), ap = B.aiProd || {}, done = Object.entries(ap), ready = S.cfg.ai.on && S.cfg.ai.key && S.cfg.ai.consent;
  if (!gaps.length && !done.length) return '';
  const data = bbGapData(B);
  let h = `<h3 class="h3" style="margin-top:16px">Construction items with no rate in the library ${gaps.length ? qchip(gaps.length + ' groups', 'warn') : qchip('none', 'ok')}</h3><p class="hint" style="margin-top:0">Your library always has priority. For the gaps, Claude can suggest a low, typical and high output per crew. Every figure stays an unconfirmed suggestion until you accept it, and nothing is filled in silently. Claude has no verified source for your region: use it as a starting point and replace it with your own data.</p>`;
  if (gaps.length) h += `<div class="actions"><button class="btn" data-bapr="1" ${ready ? '' : 'disabled'}>Ask Claude for rate suggestions (${Math.min(40, gaps.length)} groups, about $${estimateCost('bb_prod', JSON.stringify(data).length + BB_PROD_SYS.length, 2500).toFixed(3)})</button>${ready ? '' : '<span class="hint">Needs AI switched on, a key and the consent box in Setup → AI.</span>'}</div><details><summary class="hint">Show exactly what would be sent (descriptions, units and quantities only; no prices or names)</summary><pre style="white-space:pre-wrap;font-size:12px">${esc(JSON.stringify(data, null, 1))}</pre></details>`;
  const rows = [...gaps.map(g => ({ g, a: ap[g.key] })), ...done.filter(([k]) => !gaps.some(g => g.key === k)).map(([k, a]) => ({ g: { key: k, unit: a.unit, desc: a.desc, n: a.n, qty: a.qty }, a }))].filter(x => x.a);
  if (rows.length) h += qtbl(['Work', 'Unit', 'Low', 'Typical', 'High', 'Crew / conditions / basis', 'Confidence', 'Use', 'Status', ''], rows.map(({ g, a }) => `<tr><td>${esc(dtr(g.desc, 60))}<br><small>${g.n} item(s)</small></td><td>${esc(g.unit)}</td><td class="n">${a.low}</td><td class="n">${a.typical}</td><td class="n">${a.high}</td><td><small><b>Crew:</b> ${esc(a.crew || '')}<br><b>Conditions:</b> ${esc(a.conditions || '')}<br><b>Basis:</b> ${esc(a.basis || 'no verified source')}<br><b>Unsure:</b> ${esc(a.unsure || '')}</small></td><td>${esc(a.confidence || '')}</td><td><select data-bapu="${esc(g.key)}"><option value="low" ${a.use === 'low' ? 'selected' : ''}>Low</option><option value="typical" ${(a.use || 'typical') === 'typical' ? 'selected' : ''}>Typical</option><option value="high" ${a.use === 'high' ? 'selected' : ''}>High</option></select></td><td>${a.status === 'accepted' ? qchip('Accepted by you', 'ok') : a.status === 'rejected' ? qchip('Rejected', 'bad') : qchip('AI suggested, not confirmed', 'warn')}</td><td><button class="btn sm" data-bapa="${esc(g.key)}">${a.status === 'accepted' ? 'Withdraw' : 'Accept'}</button> <button class="btn sm" data-bapx="${esc(g.key)}">Reject</button></td></tr>`), { h: 340 });
  return h;
}
document.addEventListener('click', async e => {
  if (S.step !== 'builder') return; const B = S.bb; let el;
  if (e.target.closest('[data-bapr]')) {
    if (!aiReady()) return; const data = bbGapData(B); if (!data.length) return; toast('Asking Claude for rate suggestions...');
    try { const txt = await callClaude('bb_prod', BB_PROD_SYS, JSON.stringify(data), 3500), f = parseJson(txt); if (!Array.isArray(f)) throw new Error('Claude did not return a list I could read.'); B.aiProd = B.aiProd || {}; const gm = new Map(E.bbGaps(B).map(g => [g.key, g]));
      for (const x of f) { const g = gm.get(x.id); if (!g || !(+x.typical > 0)) continue; const lo = +x.low > 0 ? +x.low : +x.typical, hi = +x.high > 0 ? +x.high : +x.typical; B.aiProd[x.id] = { low: lo, typical: +x.typical, high: hi, crew: x.crew, conditions: x.conditions, basis: x.basis, confidence: x.confidence, unsure: x.unsure, use: 'typical', status: 'suggested', unit: g.unit, desc: g.desc, n: g.n, qty: g.qty }; }
      toast('Suggestions received. They are not used until you accept them.', 'ok'); } catch (er) { console.error(er); toast(er.message, 'bad'); } viewBuilder(); return;
  }
  if ((el = e.target.closest('[data-bapa]'))) { const a = (B.aiProd || {})[el.dataset.bapa]; if (a) { a.status = a.status === 'accepted' ? 'suggested' : 'accepted'; B.ack = false; B.logicOk = false; bbRefresh(); viewBuilder(); } return; }
  if ((el = e.target.closest('[data-bapx]'))) { const a = (B.aiProd || {})[el.dataset.bapx]; if (a) { a.status = 'rejected'; B.ack = false; B.logicOk = false; bbRefresh(); viewBuilder(); } return; }
});
document.addEventListener('change', e => { if (S.step !== 'builder') return; const el = e.target; if (el.dataset && el.dataset.bapu) { const a = (S.bb.aiProd || {})[el.dataset.bapu]; if (a) { a.use = el.value; S.bb.ack = false; S.bb.logicOk = false; bbRefresh(); viewBuilder(); } } });
